  ('voc', '2026-12-15', '09:00', '17:17', 'The 180-Second Pitch-a-Thon aims to give VIT Chennai students a fast-paced, hands-on startup simulation where teams build a 3-slide business model on the spot and pitch it live in under 3 minutes. Through screening, strict time-boxing, and a nominal registration fee, the event is designed to filter out passive attendees seeking only an OD and ensure genuine engagement. It''s expected to teach practical business concepts — pricing, margins, and startup costs — while helping VITFAM extend its reach to engineering and tech students beyond typical business majors.', 'BUVANESH C', '9789900174', false),
  ('voc', '2026-12-16', '09:00', '16:30', 'Crypto Clash is a fun and competitive crypto trading event where participants use virtual funds to trade cryptocurrencies, make smart decisions, and compete to achieve the highest returns. Test your strategy, manage your risks, and become the ultimate Crypto Clash champion!', 'BUVANESH C', '9789900174', false),
  ('voc', '2027-01-08', '09:00', '18:00', 'AI/ML workshop', 'UMMITY SRINIVASA RAO', '7904714516', false),
